WITH exploded AS (SELECT base.id, elem.product_id, elem.qty, elem.price, elem.promo FROM carts base LATERAL VIEW OUTER EXPLODE(base.items) t AS elem) SELECT promo, ROUND(SUM(qty) / NULLIF(COUNT(CASE WHEN promo = 'BUNDLE' THEN 1 END), 0), 2) AS qty_per_bundle, SIZE(COLLECT_SET(promo)) AS num_promos, COUNT_IF(promo = 'BUNDLE') AS bundle_events FROM exploded GROUP BY promo HAVING qty_per_bundle > 0 ORDER BY qty_per_bundle DESC;
